      mu_assert("ERROR: chunk cannot be decompressed correctly", dsize >= 0);
      for (int j = 0; j < CHUNKSIZE; j++) {
        int64_t a = data_dest[j];
        mu_assert("ERROR: bad roundtrip 3", a == pos);
      }
    }
  }

